const PORTABLE = Symbol.for("pletivo.portableModule");

function visit(node, fn) {
  fn(node);
  for (const child of node.children ?? []) visit(child, fn);
}

export function remarkShout(options = {}) {
  const suffix = options.suffix ?? "";
  return (tree) => visit(tree, (node) => {
    if (node.type === "text") node.value += suffix;
  });
}
remarkShout[PORTABLE] = { module: "portable-markdown", export: "remarkShout" };

export function rehypeMark() {
  return (tree) => visit(tree, (node) => {
    if (node.type === "element" && node.tagName === "p") node.properties = { ...node.properties, className: ["marked"] };
  });
}
rehypeMark[PORTABLE] = { module: "portable-markdown", export: "rehypeMark" };
